"""Proposed complete core only. Writes this review folder, never the active corpus."""
from pathlib import Path
import html, json, sys
HERE=Path(__file__).resolve().parent
LEGAL=HERE.parents[2]
sys.path.insert(0,str(LEGAL))
from run_exhaustive import validate_answer
S=json.loads((HERE/'source.json').read_text());by={s['number']:s for s in S}
E='l’entrée en vigueur de la loi instituant le contrat de travail unique'
N='les contrats conclus à compter de '+E
def P(*values):return ''.join('<p>'+v+'</p>' for v in values)
def old(n):return P('Pour les contrats conclus avant '+E+', les règles suivantes demeurent applicables :')+by[n]['source_xml']
A={}
def put(n,body,reason,notes,benefit):
 s=by[n];a={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
 a.update(proposed_xml=body,reason=reason,review_notes=notes,benefit_review=benefit,status='rewrite_draft')
 if s.get('previous_draft'):a['prior_proposal_sha256']=s['previous_draft']['proposed_sha256']
 A[n]=a
common='Proposition réservée au paquet de contrôle, non enregistrée et non publiée. Date commune à fixer par la loi sans date inventée. Préserver les sources et les droits antérieurs ; les contrats antérieurs ne sont pas rétroactivement soumis aux nouvelles charges. '

put('L1221-2',P('Tout contrat de travail relevant du présent code et conclu à compter de '+E+' est conclu pour une durée indéterminée. Il constitue le contrat de travail unique. Il ne peut prévoir sa fin automatique à une date, au retour d’une personne remplacée ou à l’achèvement d’une tâche, d’une formation, d’un chantier ou d’une mission.','Une formation, une affectation ou une mission peut avoir une durée déterminée sans que cette durée fixe le terme du contrat de travail. La fin du contrat intervient selon les règles de rupture qui lui sont applicables.','Les contrats conclus avant cette date, les droits nés de leur exécution et les litiges relatifs à leur terme demeurent soumis aux dispositions transitoires de la loi. Aucune nouvelle embauche à durée déterminée ne peut résulter d’un renouvellement ou d’une reconduction décidé à compter de cette date.'),'Remplace la simple préférence pour le CDI par une interdiction opératoire de tout nouveau terme d’emploi, en distinguant la durée de formation ou de mission.',common+'Coordonner tout le titre CDD et les autorisations spéciales d’apprentissage, portage, recherche, reconversion et intérim. Le sort exact des contrats à terme en cours doit figurer dans la transition du lot CDD ; aucune conversion automatique ni perte d’ancienneté n’est créée ici.','La durée limitée d’une formation ou d’une mission reste possible sans supprimer son financement, sa rémunération ou les droits de son bénéficiaire. Les droits des contrats antérieurs sont expressément réservés ; la suppression du CDD nouveau ne supprime pas leurs créances de terme ou de précarité.')

put('L1221-19',P('Le contrat de travail unique peut stipuler une période d’essai dont la durée maximale est :','1° De trois mois pour les ouvriers et les employés ;','2° De trois mois pour les agents de maîtrise et les techniciens ;','3° De trois mois pour les cadres.','Ces plafonds s’appliquent à '+N+'. Les durées plus courtes de l’article L. 1221-22 restent applicables. L’essai ne peut être renouvelé. Sa rupture est soumise au préavis de quinze jours calendaires prévu aux articles L. 1221-25 et L. 1221-26.')+old('L1221-19'),'Maintient l’essai uniforme déjà décidé et le soumet expressément aux quinze jours, sans renouvellement.',common+'Le maintien des catégories restitue les subdivisions sources sans conserver leurs anciennes durées dans le régime nouveau. L’ancien régime deux/trois/quatre mois reste limité aux contrats antérieurs.','Les essais contractuels ou conventionnels plus courts ne sont pas relevés à trois mois. Les déductions de stage restent applicables et les contrats antérieurs conservent les règles qui leur étaient applicables ; aucun renouvellement nouveau ne peut accroître la précarité de l’essai.')
put('L1221-20',P('La période d’essai sert à l’employeur à évaluer les compétences du salarié dans le travail confié, notamment au regard de son expérience, et au salarié à apprécier si les fonctions lui conviennent.','Elle n’autorise ni une rupture discriminatoire ni une rupture étrangère à ces finalités. Pour le contrat de travail unique, le préavis de quinze jours calendaires demeure applicable.'),'Conserve les deux fonctions de l’essai et écarte sa lecture comme dispense de préavis.',common+'Aucune cause automatique de licenciement ni immunité judiciaire n’est créée. La rupture de l’essai reste distincte du licenciement après essai.','Les deux finalités protègent chaque partie. La durée plus courte éventuellement applicable et les recours pour abus ou discrimination demeurent disponibles ; le contrat unique n’impose pas de période d’essai obligatoire.')
put('L1221-21',P('La période d’essai du contrat de travail unique conclu à compter de '+E+' ne peut être renouvelée, quelle que soit la durée initialement stipulée. Toute clause ou stipulation qui prévoit ce renouvellement est réputée non écrite.')+old('L1221-21'),'Maintient l’interdiction de renouvellement du nouveau contrat et conserve l’ancien régime dans son seul champ temporel.',common+'Le régime antérieur reproduit ses trois plafonds quatre/six/huit mois et son accord de branche étendu ; il ne constitue pas une autorisation de renouveler un contrat nouveau.','La suppression du renouvellement est maintenue pour les embauches futures, même lorsque l’essai initial est inférieur à trois mois. Les clauses plus courtes ne perdent aucun effet ; les droits des contrats anciens ne sont pas transformés rétroactivement.')
put('L1221-22',P('Pour le contrat de travail unique conclu à compter de '+E+', les plafonds de l’article L. 1221-19 sont impératifs. Restent applicables les durées plus courtes prévues :','1° Par une convention ou un accord collectif applicable, quelle que soit sa date de conclusion ;','2° Par la lettre d’engagement ou le contrat de travail.','Même dans ces cas, l’essai ne peut être renouvelé.')+old('L1221-22'),'Conserve les durées plus courtes et ferme toute possibilité de renouvellement nouveau.',common+'La note de la loi 2023-171, applicable six mois après promulgation, reste historique et ne fixe pas la date de cette réforme. Le filtre de 2008 est conservé uniquement dans le régime antérieur reproduit.','Les accords et clauses prévoyant un essai plus court restent ouverts aux nouvelles embauches. Aucun accord expiré n’est remis en vigueur et aucune durée longue ancienne n’est étendue au contrat unique ; le renouvellement est toujours exclu dans ce régime.')
put('L1221-23',P('La période d’essai ne se présume pas. Elle doit être expressément stipulée dans la lettre d’engagement ou le contrat de travail.','Pour '+N+', aucune stipulation ne peut en permettre le renouvellement. Pour les contrats antérieurs dont le renouvellement reste licite, sa possibilité doit elle aussi être expressément stipulée ; elle ne se présume pas.'),'Coordonne l’exigence d’essai exprès avec l’interdiction nouvelle de renouvellement.',common+'La clause de renouvellement d’un contrat antérieur ne vaut pas accord à sa mise en œuvre. Le régime des autres contrats est coordonné dans les lots spécialisés.','L’absence de clause expresse continue à dispenser le salarié d’essai. Une durée plus courte reste possible et les anciens renouvellements ne deviennent pas automatiques. Aucune obligation nouvelle d’instituer un essai ou de le renouveler n’est créée.')
put('L1221-24',P('Lorsque l’entreprise embauche, dans les trois mois suivant sa fin, un stagiaire ayant accompli pendant sa dernière année d’études un stage intégré à un cursus pédagogique, elle déduit la durée du stage de l’essai. Cette déduction peut réduire l’essai de moitié au plus, sauf accord collectif plus favorable. Si l’emploi correspond aux activités confiées pendant ce stage, la déduction est intégrale.','Lorsque l’entreprise embauche à l’issue d’un stage de plus de deux mois, au sens de l’article L. 124-6 du code de l’éducation, cette durée est prise en compte pour l’ouverture et le calcul des droits d’ancienneté. Elle est notamment retenue pour le seuil et le calcul de l’indemnité de rupture lorsque ces conditions sont remplies.'),'Conserve l’imputation du stage et rend explicite son effet sur le nouveau seuil d’ancienneté.',common+'Le second alinéa n’est pas soumis aux conditions de dernière année et de trois mois du premier. Pas de nouvel essai complet lors d’une conversion.','La déduction totale ou partielle du stage, les accords plus favorables et l’ancienneté issue du stage sont conservés pour les situations futures éligibles. La franchise d’indemnité ne remet pas le compteur d’ancienneté à zéro et n’efface pas le stage reconnu.')
put('L1221-25',P('Lorsque l’employeur rompt la période d’essai d’un contrat de travail unique conclu à compter de '+E+', il respecte un préavis de quinze jours calendaires, quelle que soit la durée de présence du salarié. Ce préavis court selon l’article L. 1234-3.','Le préavis ne prolonge pas la période d’essai. S’il ne peut être entièrement exécuté avant son terme, l’employeur met fin au travail à ce terme et verse une indemnité compensatrice pour la fraction du préavis restant à courir. Cette fraction n’allonge pas la période d’essai ni l’ancienneté effective au-delà du terme ainsi fixé. Si le travail se poursuit après le terme de l’essai, le contrat ne peut être rompu selon le régime de l’essai ; les règles ordinaires de rupture s’appliquent.','L’indemnité compensatrice couvre les salaires et avantages du préavis non exécuté, indemnité compensatrice de congés payés comprise. Elle reste due même si aucune indemnité ordinaire de rupture n’est ouverte. La faute grave ne supprime pas ce préavis payé dans le régime nouveau.')+old('L1221-25'),'Remplace les délais nouveaux de 24 h, 48 h, deux semaines et un mois par quinze jours, et règle expressément le dépassement du terme d’essai.',common+'Choix éditorial à valider : maintien de la solution française de compensation du reliquat plutôt qu’une prolongation déguisée de l’essai. Le contrat finit au terme de l’essai dans cette seule hypothèse ; la fraction payée n’est pas artificiellement ajoutée à l’ancienneté. Aucun préavis nul en essai court.','Le préavis payé et les congés afférents ne sont pas absorbés par la franchise d’un an. Les délais antérieurs restent dans le régime ancien. La fin de l’essai n’autorise aucune disparition de salaire ; le salarié reçoit les quinze jours sous forme d’exécution et, pour le reliquat, de compensation.')
put('L1221-26',P('Le salarié qui rompt l’essai d’un contrat de travail unique conclu à compter de '+E+' respecte un préavis de quinze jours calendaires, quelle que soit sa durée de présence. Il le notifie selon l’article L. 1234-3.','Ce préavis n’allonge pas la période d’essai. Si son exécution se poursuit après le terme de l’essai, le salarié demeure en contrat de travail unique jusqu’à la fin du préavis ; la notification vaut alors démission pour la fraction exécutée après l’essai, sans faire recommencer un second préavis. Le salarié et l’employeur peuvent convenir d’une dispense d’exécution, sans que le présent article crée une indemnité ordinaire à la charge de l’employeur.')+old('L1221-26'),'Fixe quinze jours également au salarié et évite un second préavis lorsque l’essai s’achève pendant le délai.',common+'Les délais de 24/48 h ne demeurent applicables qu’aux contrats antérieurs. La poursuite demandée par le salarié au-delà de l’essai ne confère aucun droit à un nouvel essai ni à une indemnité ordinaire de licenciement.','Le préavis ne prolonge pas l’évaluation et n’est jamais doublé du fait du franchissement de son terme. Une dispense d’exécution consentie reste possible ; les salaires et congés acquis restent dus, sans assimiler cette démission à une rupture employeur.')

put('L1231-1',P('Le contrat de travail unique peut être rompu à l’initiative de l’employeur ou du salarié, ou d’un commun accord, selon les dispositions du présent titre.','Pour '+N+', la rupture unilatérale est soumise à un préavis de quinze jours calendaires pour chacune des parties. Cette durée ne dispense pas des motifs licites, des procédures, des autorisations et des protections applicables à la rupture.','Pendant l’essai, les règles propres à celui-ci restent applicables, notamment les articles L. 1221-25 et L. 1221-26, qui imposent également quinze jours de préavis. L’exclusion des autres dispositions du présent titre pendant l’essai ne vaut pas dispense de ce préavis.','Les contrats conclus avant cette date conservent leur régime de rupture, sous réserve de la transition du calcul de l’indemnité prévue à l’article L. 1234-9.'),'Remplace l’exclusion générale de l’essai par une articulation explicite, sans créer une rupture sans motif ni supprimer les procédures collectives.',common+'Convention OIT 158 : validité du motif, défense, recours et durée raisonnable de préavis restent à contrôler. Les calendriers collectifs ne sont pas réduits à quinze jours.','Les protections particulières de L1231-2 et les recours subsistent. Les indemnités distinctes, congés et salaires ne sont pas supprimés par le préavis uniforme ; les relations antérieures conservent leur régime de préavis et leur composante d’indemnité acquise.')
put('L1234-1',P('Pour '+N+', le salarié dont l’employeur prend l’initiative de rompre le contrat bénéficie d’un préavis de quinze jours calendaires, indépendamment de son ancienneté. La faute grave n’exonère pas l’employeur de ce préavis ; si elle rend impossible le maintien au travail, le préavis est payé sans être exécuté.','Cette durée se substitue aux durées et conditions d’ancienneté de préavis des conventions, accords, contrats et usages pour les contrats nouveaux. Les procédures collectives, autorisations et protections qui conditionnent la rupture restent applicables.')+old('L1234-1'),'Supprime les seuils de six mois et deux ans du préavis nouveau et applique quinze jours, y compris sous forme payée en cas de faute grave.',common+'L5213-9, L7112-2 et L7313-9 nécessitent les coordinations expressément confiées à root ; ne pas annoncer une uniformité achevée avant leur intégration. Vérifier conventionalité du délai pour longues anciennetés.','Le droit au salaire de préavis subsiste en cas de dispense et même de faute grave pour le nouveau contrat. Les durées plus favorables des contrats antérieurs restent protégées ; aucune réduction rétroactive du préavis déjà ouvert n’est prévue.')
put('L1234-2',P('Pour '+N+', toute clause imposant un préavis unilatéral d’une durée différente des quinze jours calendaires prévus à l’article L. 1234-1 est réputée non écrite. Une dispense d’exécution ne change pas, à elle seule, le terme du préavis ni les sommes dues selon l’article L. 1234-5.')+old('L1234-2'),'Rend opposable la durée nouvelle sans confondre durée du contrat et dispense de travail.',common+'Choix de durée fixe, non de simple minimum. Les indemnités conventionnelles plus favorables ne sont pas plafonnées par cette règle de délai.','Les contrats antérieurs conservent la nullité des clauses réduisant leur préavis protecteur. Pour les contrats nouveaux, la dispense d’exécution ne devient ni une renonciation à la rémunération ni une disparition du délai payé ; les indemnités plus favorables restent distinctes.')
put('L1234-3',P('Le préavis de licenciement commence à la date de présentation au salarié de la lettre recommandée lui notifiant le licenciement.','Pour le contrat de travail unique conclu à compter de '+E+', les quinze jours calendaires se comptent à partir du lendemain de cette présentation ; le préavis expire à la fin du quinzième jour, même non travaillé. Si la loi autorise une autre forme de notification, la date de sa réception ou de sa remise au destinataire se substitue à celle de présentation.','Pour une rupture à l’initiative du salarié, le délai nouveau se compte de la même manière à partir du lendemain de la réception par l’employeur de sa notification écrite. Tout moyen établissant cette date de réception est admis. Le délai n’est pas reporté du seul fait qu’il comprend un jour non travaillé.'),'Fixe le calcul calendaire et le point de départ symétrique sans rendre facultatives les formes légales du licenciement.',common+'Choix de computation explicite : lendemain de la réception, quinze jours entiers. L1232-6 garde sa lettre recommandée ; aucune nouvelle faculté générale de notifier un licenciement par simple message.','La preuve de réception protège les deux parties et évite un déclenchement au seul envoi. Aucun préavis payé n’est perdu parce que des jours fériés ou repos traversent le délai ; les autres règles de suspension ayant un fondement distinct ne sont pas effacées.')
put('L1234-4',P('L’inexécution du préavis de licenciement ne fait pas avancer la date de fin du contrat. Cette règle s’applique aussi aux quinze jours du contrat de travail unique.','La fin de l’essai et la compensation de la fraction de préavis qui ne peut y être exécutée demeurent régies par l’article L. 1221-25. Les reports de terme qui résultent d’une protection ou d’un dispositif collectif distinct conservent leurs effets.'),'Applique le maintien du terme au délai nouveau et identifie expressément le cas limité de fin d’essai.',common+'Ne pas assimiler la dispense de travail à la rupture immédiate du contrat ordinaire ; le préavis ordinaire non exécuté entre dans l’ancienneté de L1234-9.','Le salarié dispensé de travailler conserve la durée contractuelle de préavis et les rémunérations attachées. Le cas spécifique de l’essai comporte une compensation expresse, pas une déchéance du préavis ni de ses congés payés.')
put('L1234-5',P('Pour '+N+', le préavis dont l’employeur dispense l’exécution est compensé par une indemnité égale aux salaires et avantages que le salarié aurait perçus en travaillant jusqu’à son terme, indemnité de congés payés comprise. La même compensation est due lorsque l’employeur n’a pas respecté les quinze jours, y compris en cas de faute grave.','Cette indemnité est distincte de l’indemnité ordinaire de rupture. La franchise d’un an et le plafond de six mois de cette dernière ne lui sont pas applicables. Elle se cumule, dans leurs conditions propres, avec l’indemnité de licenciement et l’indemnité prévue à l’article L. 1235-2.','Une inexécution à l’initiative du salarié ne lui ouvre pas, par elle-même, un droit au paiement du travail qu’il refuse d’accomplir. Les dispenses d’exécution convenues restent soumises à leurs conditions propres.')+old('L1234-5'),'Conserve le préavis rémunéré et empêche que la franchise indemnitaire efface quinze jours de salaire.',common+'Le nouveau paiement en cas de faute grave résulte du préavis uniforme expressément retenu. Les dommages éventuels d’une démission abusive ne sont pas un forfait nouveau.','Le paiement du préavis et des congés afférents est maintenu, hors plafond et franchise de l’indemnité ordinaire. La dispense par l’employeur n’est pas assimilée à une dispense non rémunérée demandée par le salarié ; le cumul avec les réparations licites est conservé.')
put('L1234-6',P('Lorsque la fermeture temporaire ou définitive de l’établissement ou la réduction de son horaire habituel au-dessous de la durée légale applicable empêche l’exécution de tout ou partie du préavis, le salaire de référence du préavis est calculé :','1° Pour le salarié à temps plein, sur la durée légale ou conventionnelle qui lui est applicable dans l’entreprise ;','2° Pour le salarié à temps partiel, sur la durée fixée par son contrat.','Ces règles s’appliquent au préavis de quinze jours du contrat de travail unique sans autoriser de baisse de salaire contractuel.'),'Préserve la base salariale du préavis nouveau en cas de fermeture ou de réduction d’horaire.',common+'Coordination avec les durées hebdomadaires 35/40 heures déjà proposées ; aucune annualisation portée à 40 heures par cet article.','La fermeture ou la réduction d’activité ne réduit pas le salaire servant à payer le préavis. Les durées conventionnelles et contractuelles plus favorables demeurent pertinentes ; le temps partiel garde sa propre base et aucun plafond d’indemnité de rupture ne s’y applique.')
put('L1234-7',P('La cessation d’activité de l’entreprise ne dispense pas l’employeur de respecter ou de payer le préavis. Pour '+N+', sa durée est de quinze jours calendaires.','La cessation résultant d’un véritable cas de force majeure reste régie par les articles L. 1234-12 et L. 1234-13.'),'Conserve le préavis en cas de simple cessation et distingue l’événement externe de force majeure.',common+'Une difficulté économique ou une cessation choisie ne suffit pas à qualifier la force majeure.','La cessation ordinaire ne supprime ni les quinze jours de préavis ni leur compensation. Le régime spécial du sinistre est réservé, et les droits des contrats antérieurs ne sont pas réduits du seul fait que l’entreprise ferme.')
put('L1234-8',P('Pour '+N+', aucune durée d’ancienneté n’est exigée pour le préavis de quinze jours calendaires. Les suspensions du contrat ne réduisent pas ce délai.','Pour les contrats conclus avant cette date, les suspensions prévues par la loi, une convention ou un accord collectif, le contrat ou les usages n’interrompent pas l’ancienneté retenue pour les 2° et 3° de l’article L. 1234-1. Leur durée n’entre toutefois pas dans le calcul de l’ancienneté exigée pour ces dispositions, sauf pour la suspension des élus locaux mentionnée au premier alinéa de l’article L. 3142-88.'),'Retire du préavis nouveau les seuils devenus sans objet sans supprimer les assimilations favorables de l’ancien régime.',common+'L’ancienneté pour l’indemnité reste distinctement régie par L1234-11. L3142-88 conserve son propre champ.','L’absence de seuil garantit quinze jours dès l’embauche. Les protections des élus locaux restent applicables dans l’ancien régime ; aucune suspension n’est transformée en rupture d’ancienneté et aucune règle d’indemnité n’est supprimée par coordination du préavis.')

put('L1234-9',P('Le salarié dont le contrat de travail unique a été conclu à compter de '+E+' et est rompu à l’initiative de l’employeur a droit à l’indemnité ordinaire de rupture lorsqu’il atteint au moins un an d’ancienneté ininterrompue chez cet employeur à la date de fin effective du contrat. Le préavis exécuté ou non entre dans cette ancienneté, sous réserve de la fin d’essai régie par l’article L. 1221-25. L’indemnité n’est pas due en cas de faute grave.','Avant ce premier anniversaire, aucune indemnité ordinaire de rupture n’est due. À compter de ce seuil, son montant est égal à 0,20 mois de salaire brut de référence par année de l’ancienneté totale reconnue, au prorata des mois complets pour une année incomplète, dans la limite de six mois de ce salaire. Le calcul ne repart pas de zéro au premier anniversaire.','La rupture à l’initiative du salarié n’ouvre pas droit à cette indemnité ordinaire. Cette règle ne supprime ni salaires, congés acquis, indemnités de préavis, réparations d’une illégalité, ni indemnités spéciales fondées sur une autre disposition.','Pour les contrats conclus avant cette entrée en vigueur, la condition d’ouverture antérieure de huit mois d’ancienneté et l’exception de faute grave restent applicables. La part correspondant aux services accomplis avant cette date est calculée selon les taux légaux applicables la veille de cette date. Elle s’ajoute à la part correspondant aux services accomplis à compter de cette date, calculée à 0,20 mois de salaire par année et seule plafonnée à six mois. Le salaire de référence des deux parts est déterminé à la rupture.','Une indemnité conventionnelle ou contractuelle plus favorable et les dommages et intérêts ne sont pas limités par ce plafond. Un décret fixe le salaire brut de référence, le prorata et l’affectation des périodes entre les deux composantes sans double compte.'),'Institue la franchise nouvelle d’un an, le calcul sur toute l’ancienneté dès le seuil et le barème confirmé, uniquement à initiative employeur, avec l’ancienne composante protégée.',common+'POINT À VALIDER : exception de faute grave maintenue pour l’indemnité, car sa suppression n’a pas été expressément décidée ; elle ne supprime plus le préavis nouveau. La condition de huit mois est réservée aux contrats antérieurs, comme transition protectrice. Le plafond global ne s’applique qu’aux contrats nouveaux ; la somme des parts d’un ancien contrat peut dépasser six mois.','Les droits d’ancienneté antérieure ne sont pas écrasés par le nouveau plafond. Les indemnités plus favorables, congés, salaires et réparations demeurent distincts. Pour le contrat nouveau, un an atteint pendant le préavis ouvre le calcul sur toute l’ancienneté ; aucun premier exercice n’est retiré de l’assiette.')
put('L1234-10',P('La cessation d’activité de l’entreprise ne libère pas l’employeur de l’indemnité due selon l’article L. 1234-9. L’ouverture du droit, la franchise applicable, les composantes d’ancienneté et leur plafond sont appréciés selon cet article.','Les régimes de force majeure et de sinistre prévus aux articles L. 1234-12 et L. 1234-13 demeurent distincts.'),'Empêche de faire de la fermeture une dispense d’indemnité en dehors de la franchise autorisée.',common+'La condition « si elle est due » est conservée par le renvoi au droit ouvert, sans créer une indemnité avant un an pour une cessation ordinaire nouvelle.','Le salarié dont le droit est ouvert conserve sa créance malgré la fermeture. La composante d’ancienneté antérieure demeure protégée et la franchise n’est pas étendue aux indemnités spéciales de sinistre ou aux autres créances salariales.')
put('L1234-11',P('Les suspensions du contrat prévues par la loi, une convention ou un accord collectif, le contrat ou les usages n’interrompent pas l’ancienneté retenue pour le droit à l’indemnité de l’article L. 1234-9.','Leur durée n’entre toutefois pas dans l’ancienneté exigée, sauf celle de la suspension des élus locaux mentionnée au premier alinéa de l’article L. 3142-88 et les assimilations résultant d’autres dispositions applicables.','Pour le contrat de travail unique nouveau, l’ancienneté reconnue s’apprécie à la fin effective du contrat, préavis compris selon l’article L. 1234-9. Lorsque le seuil d’un an est atteint, toute cette ancienneté reconnue est retenue pour le calcul ; aucune année de franchise n’est retranchée. Pour les contrats antérieurs, la même période ne peut être affectée deux fois aux composantes antérieure et nouvelle.'),'Coordonne suspension, date d’appréciation et ancienneté totale sans assimiler indistinctement toute absence à du service.',common+'Maintenir les règles spéciales de maternité, accident, stage et mandats ; pas de compteur réinitialisé à la conversion.','La continuité de l’ancienneté, l’exception des élus locaux et les autres assimilations favorables subsistent. Le préavis ordinaire compte pour franchir le seuil et pour l’assiette. Les droits d’un ancien contrat ne sont ni doublés artificiellement ni supprimés par l’affectation entre composantes.')
put('L1234-12',P('La cessation de l’entreprise résultant d’un cas de force majeure libère l’employeur de l’obligation de préavis et de l’indemnité ordinaire prévue à l’article L. 1234-9.','Cette règle ne concerne pas une rupture à l’initiative de l’employeur fondée sur une simple cessation choisie ou sur des difficultés économiques. Le sinistre relevant de la force majeure reste soumis à l’indemnité compensatrice prévue à l’article L. 1234-13.'),'Conserve l’événement de force majeure distinct d’une rupture à initiative employeur, et exclut son emploi pour contourner les quinze jours.',common+'POINT À VALIDER : la force majeure, événement externe sans initiative volontaire, reste une exception préexistante ; le préavis uniforme concerne les ruptures à initiative de l’une des parties. Pas de qualification automatique de force majeure.','La dispense n’est pas élargie aux fermetures ordinaires. Le droit spécial à compensation en cas de sinistre est maintenu et les créances salariales antérieures ne sont pas effacées ; la franchise ne fournit aucune dispense nouvelle de préavis à un licenciement économique.')
put('L1234-13',P('Si un sinistre relevant de la force majeure entraîne la rupture du contrat à durée indéterminée ou du contrat de travail unique, l’employeur verse au salarié une indemnité compensatrice.','Elle est égale à la somme des montants qui auraient résulté de l’article L. 1234-5 pour le préavis et de l’article L. 1234-9 pour l’indemnité ordinaire. La première composante reste due lorsque la franchise d’un an rend la seconde nulle. Pour un contrat antérieur, les droits d’ancienneté protégés par l’article L. 1234-9 entrent dans la seconde composante.'),'Conserve la compensation spéciale du sinistre et sépare la franchise de l’indemnité du salaire de préavis.',common+'La somme n’est pas globalement plafonnée à six mois ; elle reste à la charge de l’employeur.','L’avantage particulier du sinistre subsiste pour les situations futures : au moins la compensation du préavis lorsque la composante ordinaire n’est pas ouverte. Le plafond de la composante nouvelle ne réduit ni le préavis ni les droits antérieurs protégés.')
put('L1234-14',P('Les articles L. 1234-1, L. 1234-8, L. 1234-9 et L. 1234-11 s’appliquent, lorsque leurs conditions propres sont remplies :','1° Aux agents et salariés mentionnés à l’article L. 5424-1, autres que les fonctionnaires et militaires ;','2° Aux salariés soumis au même statut légal que celui applicable aux entreprises publiques.','Pour chacun de ces articles, les règles nouvelles ou antérieures s’appliquent selon son champ et sa transition ; le présent article ne convertit pas un contrat public distinct en contrat de travail unique.'),'Conserve les catégories couvertes sans étendre implicitement le contrat privé unique à la fonction publique.',common+'Les deux catégories restent distinctes et l’exclusion fonctionnaires/militaires ne migre pas au 2°.','Les agents et salariés déjà bénéficiaires conservent leurs droits sous les mêmes conditions. Aucun régime statutaire autonome n’est absorbé par le plafond de six mois et la composante d’ancienneté antérieure suit sa transition protectrice.')
put('L1234-15',P('Dans la Moselle, le Bas-Rhin et le Haut-Rhin, le préavis du contrat de travail unique conclu à compter de '+E+' est de quinze jours calendaires pour chacune des parties, selon les articles L. 1234-1 et L. 1237-1.','Pour les contrats conclus avant cette date, le salarié a droit à un préavis :','1° D’un jour si la rémunération est fixée par jour ;','2° D’une semaine si elle est fixée par semaine ;','3° De quinze jours si elle est fixée par mois ;','4° De six semaines si elle est fixée par trimestre ou période plus longue.'),'Coordonne expressément le droit local au lieu de laisser subsister quatre durées concurrentes pour le nouveau contrat.',common+'Champ territorial de la sous-section maintenu ; aucune assimilation du rythme de fixation à celui de paiement effectif.','Les durées antérieures plus protectrices restent applicables aux anciens contrats et ne sont pas réduites rétroactivement. Les quinze jours nouveaux s’appliquent aux deux parties ; le droit à la recherche d’emploi de L1234-17 subsiste.')
put('L1234-16',P('Les catégories suivantes bénéficient, pour un contrat conclu avant '+E+', d’un préavis de six semaines dans le champ territorial de la présente sous-section :','1° Les professeurs et les personnes employées chez des particuliers ;','2° Les commis commerciaux de l’article L. 1226-24 ;','3° Les salariés à rémunération fixe assurant de manière permanente la direction ou la surveillance d’une activité ou d’une partie de celle-ci, ou ceux chargés de services techniques exigeant une certaine qualification.','Pour le contrat de travail unique conclu à compter de cette date, ces catégories relèvent des quinze jours calendaires de l’article L. 1234-15.'),'Limite les six semaines locales aux anciens contrats et règle les catégories sans renvoi implicite.',common+'Préserver la portée des deux branches du 3°, sans soumettre tous les services techniques à une condition nouvelle de rémunération fixe.','Le préavis de six semaines reste acquis dans le régime des contrats antérieurs. Les autres protections de ces professions ne sont pas supprimées par la seule coordination du délai ; la recherche d’emploi pendant le préavis reste applicable.')
put('L1234-17',P('Pendant le préavis, l’employeur accorde au salarié qui le demande un délai raisonnable pour rechercher un nouvel emploi. Cette faculté reste ouverte pendant les quinze jours calendaires du contrat de travail unique.'),'Maintient la recherche d’emploi dans le préavis raccourci.',common+'Aucun nombre d’heures ni régime de rémunération nouveau n’est inventé. Le champ local de la sous-section reste inchangé.','Le droit favorable de recherche d’emploi demeure ouvert aux embauches futures et n’est pas réputé sans objet parce que le préavis est plus court. La demande du salarié et l’obligation d’accorder un délai raisonnable sont conservées.')
put('L1234-17-1',P('Pour les contrats conclus avant '+E+', les dispositions de la présente sous-section s’appliquent à défaut de dispositions légales ou conventionnelles ou d’usages fixant un préavis plus long. Elles s’appliquent également à la rupture du CDI à l’initiative du salarié.','Pour les contrats de travail uniques conclus à compter de cette date, le préavis est celui de quinze jours calendaires fixé par l’article L. 1234-15 pour chacune des parties. Le droit prévu à l’article L. 1234-17 demeure applicable.'),'Réserve la priorité locale des durées plus longues aux anciens contrats et conserve l’avantage distinct de recherche d’emploi.',common+'Coordination explicite de la démission locale ; aucune extension à une autre région.','Les anciens contrats gardent la priorité aux délais plus longs ; les nouveaux gardent le délai raisonnable de recherche d’emploi. La suppression de durées concurrentes n’efface aucune rémunération ou indemnité ayant un fondement distinct.')
put('L1234-18',P('Un décret en Conseil d’État détermine l’application des articles L. 1234-1 à L. 1234-14, notamment le calcul des quinze jours calendaires et de leur compensation, le salaire de référence et la répartition de l’ancienneté antérieure et nouvelle pour les contrats déjà conclus.','Ce décret ne peut modifier la franchise d’un an, le taux de 0,20 mois par année ou le plafond de six mois définis par la loi, ni réduire la composante d’ancienneté antérieure préservée par l’article L. 1234-9.'),'Coordonne l’habilitation au nouveau régime sans déléguer au règlement les paramètres décidés.',common+'Le calcul précis du mois chevauchant l’entrée en vigueur ne doit perdre aucun service ni le compter deux fois.','L’habilitation est encadrée pour protéger les droits antérieurs et ne permet pas de diminuer par décret les indemnités plus favorables ou les créances distinctes. La nouvelle franchise est limitée à l’indemnité ordinaire dans son champ légal.')

put('L1237-1',P('Le salarié qui prend l’initiative de rompre un contrat de travail unique conclu à compter de '+E+' respecte un préavis de quinze jours calendaires, notifié et calculé selon l’article L. 1234-3. Cette démission n’ouvre pas droit à l’indemnité ordinaire de rupture de l’article L. 1234-9.','Les droits au salaire et aux congés acquis, les dispenses légales particulières et les recours fondés sur une illégalité demeurent distincts.')+old('L1237-1'),'Fixe la durée symétrique de la démission et distingue le départ volontaire de l’indemnité employeur.',common+'Les dispenses de grossesse, d’éducation d’un enfant et de clause de conscience nécessitent une coordination explicite de root ; elles ne sont pas effacées par le texte général.','Les droits au salaire et aux congés ne disparaissent pas lors d’une démission. Les dispenses particulières restent applicables tant qu’elles ne sont pas expressément coordonnées ; les délais conventionnels des contrats antérieurs ne sont pas remplacés rétroactivement.')
put('L1237-6',P('L’employeur qui décide une mise à la retraite respecte le préavis de l’article L. 1234-1 : quinze jours calendaires pour le contrat de travail unique conclu à compter de '+E+', et la durée applicable au contrat antérieur dans les autres cas.','Ce délai ne dispense pas de remplir les conditions de mise à la retraite.'),'Applique quinze jours à la mise à la retraite sans supprimer ses conditions de fond.',common+'Les âges et l’interrogation préalable de L1237-5 ne sont ni supprimés ni ramenés à quinze jours.','L’ancien préavis reste protégé pour les contrats antérieurs et l’indemnité spécifique de mise à la retraite reste due dans ses conditions propres. Aucun âge nouveau ni départ automatique à la pension n’est créé.')
put('L1237-7',P('Le salarié mis à la retraite bénéficie d’une indemnité spécifique au moins égale au montant calculé selon le barème de l’article L. 1234-9 et ses textes d’application. Ce minimum se calcule sans importer la condition d’ouverture propre au licenciement ; pour le contrat nouveau, il est proratisé selon l’ancienneté, même inférieure à un an.','Pour les contrats antérieurs à '+E+', la composante d’ancienneté accomplie avant cette date est préservée ; elle s’ajoute à la composante nouvelle, seule plafonnée à six mois. Le salaire de référence est celui de la rupture.','Un salarié ne peut bénéficier que d’une indemnité de départ ou de mise à la retraite. Elle est attribuée lors de la première liquidation complète de la retraite.'),'Conserve l’indemnité spéciale de mise à la retraite et adapte son montant au barème sans lui importer une franchise de l’indemnité ordinaire.',common+'POINT DE PÉRIMÈTRE : indemnité spécifique maintenue avant un an, distincte de l’ordinaire expressément visée par la décision. Note 2023 : première entrée en vigueur au 1er septembre, pas date de la réforme.','Le minimum spécifique de mise à la retraite et les garanties plus favorables ne sont pas supprimés par la franchise ordinaire. Le calcul garde son prorata, la première liquidation complète et l’unicité ; les composantes antérieures ne sont pas plafonnées rétroactivement.')
put('L1237-10',P('Le salarié qui demande son départ volontaire à la retraite respecte le préavis de l’article L. 1234-1 : quinze jours calendaires pour le contrat de travail unique conclu à compter de '+E+', et la durée applicable au contrat antérieur dans les autres cas.','Le départ volontaire reste distinct d’une mise à la retraite et ne donne pas droit à l’indemnité ordinaire de rupture à initiative employeur. L’indemnité spécifique de l’article L. 1237-9 conserve son régime.'),'Coordonne le délai nouveau en conservant la distinction des deux initiatives et du régime de départ volontaire.',common+'L1237-9 et D1237-1/2 ne sont pas assimilés au taux de 0,20 mois et au plafond de six mois.','L’indemnité spéciale de retraite, ses minima et ses modalités favorables ne sont pas absorbés par la suppression de l’indemnité ordinaire en cas de démission. Les délais des contrats antérieurs demeurent applicables dans leur champ.')
put('L1237-13',P('La convention fixe les conditions de la rupture et le montant de l’indemnité spécifique de rupture conventionnelle. Celle-ci est au moins égale au montant obtenu par application du barème de l’article L. 1234-9, sans condition minimale d’ancienneté propre au licenciement. La franchise de l’indemnité ordinaire ne supprime pas ce minimum spécifique, proratisé selon les mois complets.','Pour les contrats antérieurs à '+E+', la composante d’ancienneté acquise avant cette date est préservée et s’ajoute à la composante nouvelle, seule soumise au plafond de six mois. Les conventions déjà conclues restent soumises au régime en vigueur lors de leur conclusion.','La convention fixe aussi la date de fin du contrat, qui ne peut précéder le lendemain de l’homologation. Le préavis de quinze jours applicable à une rupture unilatérale n’est pas un délai de rétractation et ne remplace pas ce contrôle.','Chaque partie peut se rétracter dans les quinze jours calendaires suivant la signature par les deux parties, par lettre adressée par tout moyen prouvant sa date de réception par l’autre partie.'),'Coordonne le minimum spécifique et la transition tout en distinguant rétractation et préavis unilatéral.',common+'POINT DE PÉRIMÈTRE : maintien du minimum spécifique avant un an ; aucune création d’indemnité ordinaire de démission. L1237-14 et L1237-15 conservent homologation/autorisation.','Le minimum de rupture amiable, le prorata des faibles anciennetés et le droit de rétractation restent disponibles aux situations futures. Le plafond de la seule part nouvelle ne supprime ni les minima plus favorables ni la composante antérieure ; le consentement demeure libre.')

put('R1234-1',P('L’indemnité ordinaire de rupture de l’article L. 1234-9 est calculée selon les années entières et, pour l’année incomplète, au prorata des mois complets de service.','Pour le contrat de travail unique nouveau, le seuil d’un an est apprécié à la fin effective du contrat, préavis inclus selon l’article L. 1234-9. Si ce seuil est atteint, le calcul porte sur l’ensemble des années et mois complets reconnus, sans retrancher la première année.','Pour les contrats antérieurs, les périodes accomplies avant et après '+E+' sont affectées à leurs composantes respectives. Un mois chevauchant cette date est réparti à proportion du service accompli de chaque côté, sans perdre ni compter deux fois une période de service.'),'Applique le prorata total et protège le mois chevauchant la réforme dans la transition.',common+'Note du décret 2017-1398 : champ historique des licenciements, mises à la retraite et ruptures conventionnelles ; ne pas l’utiliser comme date de réforme.','Les fractions de service et la première année restent dans l’assiette lorsque le droit est ouvert. Le mois à cheval n’est ni supprimé ni doublé ; les indemnités spéciales qui utilisent ce calcul conservent leur propre condition d’ouverture.')
put('R1234-2',P('Pour le contrat de travail unique conclu à compter de '+E+', l’indemnité ordinaire est égale à 0,20 mois du salaire de référence par année de l’ancienneté totale reconnue, au prorata prévu à l’article R. 1234-1, dans la limite de six mois. Aucune somme n’est due à ce titre avant le seuil d’un an de l’article L. 1234-9.','Pour les contrats conclus avant cette date, la composante correspondant aux services accomplis avant celle-ci est au moins égale :','1° À un quart de mois de salaire par année de service relevant des dix premières années d’ancienneté ;','2° À un tiers de mois de salaire par année de service au-delà des dix premières années.','La composante correspondant aux services accomplis à compter de cette date est calculée à 0,20 mois par année et seule plafonnée à six mois. Les tranches s’apprécient selon l’ordre chronologique de l’ancienneté totale, sans recréer une nouvelle tranche de dix ans.','Les composantes sont additionnées sur le même salaire de référence déterminé selon l’article R. 1234-4. Le prorata des mois et les autres créances restent régis par leurs dispositions propres.'),'Coordonne le barème intégral des nouveaux contrats et la protection de l’ancienneté antérieure des anciens contrats.',common+'Le total des deux composantes anciennes peut dépasser six mois. Le nouveau taux prime pour les services futurs, sans réinitialiser ni annuler les services antérieurs.','Les taux plus favorables des services antérieurs sont maintenus et les tranches restent chronologiques. Le plafond est limité à la part nouvelle pour les contrats anciens ; les minima conventionnels et contractuels plus favorables ne sont pas plafonnés par ce texte.')
put('R1234-4',P('Le salaire brut de référence de l’indemnité est le montant le plus favorable au salarié entre :','1° La moyenne mensuelle des douze derniers mois avant la rupture, ou, si le service a duré moins de douze mois, la moyenne des mois de rémunération précédant celle-ci ;','2° Le tiers des rémunérations des trois derniers mois. Dans ce cas, les primes et gratifications annuelles ou exceptionnelles ne sont retenues qu’à due proportion de la période à laquelle elles se rapportent.','Ce salaire est fixé à la date de rupture. Il est identique pour les composantes d’ancienneté antérieure et nouvelle de l’article L. 1234-9. Les indemnités spéciales qui renvoient à ce calcul conservent cette base même lorsque leur bénéficiaire a moins d’un an d’ancienneté.'),'Conserve la formule la plus favorable et un salaire unique à la rupture pour les deux composantes.',common+'Les règles de reconstitution liées à la maladie, à l’activité partielle ou à la rémunération atypique restent à appliquer ; la franchise ne retire pas la formule des moins de douze mois aux indemnités spécifiques.','Le choix le plus avantageux entre douze et trois mois est conservé pour les situations futures. La formule des courtes anciennetés demeure pour les indemnités spéciales et les anciennes composantes bénéficient du salaire de référence à la rupture, sans gel rétroactif.')
put('R1234-5',P('L’indemnité de licenciement ou l’indemnité ordinaire de rupture ne se cumule pas avec une autre indemnité de même nature.','Les composantes d’ancienneté antérieure et nouvelle de l’article L. 1234-9 forment une seule indemnité et doivent être additionnées. Les indemnités de préavis, de congés payés et les réparations d’une illégalité restent distinctes ; elles ne sont pas exclues par la règle de non-cumul.'),'Empêche un double emploi de même nature sans neutraliser l’addition transitoire ou les créances distinctes.',common+'Un avantage conventionnel plus favorable de même nature remplace le minimum légal selon ses conditions ; il n’est pas amputé au plafond de la seule composante nouvelle.','La règle ne fait disparaître ni le préavis, ni les congés acquis, ni les dommages distincts. L’addition des deux composantes protégées reste obligatoire et ne peut être refusée au motif qu’elle ressemblerait à un cumul de deux indemnités.')

put('R1221-34',P('Les documents remis en application de l’article L. 1221-5-1 indiquent au moins :','1° L’identité des parties ;','2° Le ou les lieux de travail et l’adresse de l’employeur si elle est distincte ;','3° Le poste, les fonctions et la catégorie professionnelle ou d’emploi ;','4° La date d’embauche ;','5° Pour une relation à durée déterminée conclue avant '+E+', sa date de fin ou sa durée prévue ; pour le contrat nouveau, sa durée indéterminée ;','6° Pour le salarié temporaire de l’article L. 1251-1, l’identité de l’entreprise utilisatrice dès qu’elle est connue ;','7° S’il existe un essai, sa durée et ses conditions, ainsi que l’interdiction de renouvellement du contrat nouveau ;','8° Le droit à formation assuré par l’employeur selon l’article L. 6321-1 ;','9° La durée du congé payé ou son mode de calcul ;','10° La procédure de cessation applicable à chaque partie. Pour le contrat de travail unique nouveau, l’information précise les quinze jours calendaires, leur point de départ, leur application à l’essai et la distinction entre indemnité ordinaire et autres sommes dues ;','11° Chaque composante de rémunération, les majorations d’heures supplémentaires, la périodicité et les modalités de paiement ;','12° La durée quotidienne, hebdomadaire ou mensuelle ou l’aménagement de référence des articles L. 3121-41 à L. 3121-47, les conditions d’heures supplémentaires ou complémentaires et, le cas échéant, de changement d’équipe ;','13° Les conventions et accords collectifs applicables ;','14° Les régimes obligatoires d’affiliation et les contrats de protection sociale complémentaire collectifs issus d’un accord ou d’une décision unilatérale, avec leurs conditions éventuelles d’ancienneté.'),'Coordonne les quatorze informations minimales sans recréer un formulaire distinct et rend lisibles les nouveaux droits.',common+'Préserver les conditions de remise, délais et supports des articles R1221-35 à R1221-41 ; la suppression de mise en demeure déjà décidée n’est pas réintroduite. Note historique : entrée en vigueur au 1er novembre 2023.','L’information sur congés, formation, rémunération et protection complémentaire demeure. Le contrat ou écrit déjà remis peut satisfaire à l’information selon L1221-5-1 ; aucun deuxième document n’est imposé pour les mêmes mentions et aucune condition d’exonération nouvelle n’est créée.')
put('L1524-1',P('À Mayotte, le contrat de travail unique conclu à compter de '+E+' relève des articles L. 1221-19 à L. 1221-26 : trois mois d’essai au plus, durées plus courtes applicables, aucun renouvellement et quinze jours calendaires de préavis pour chaque partie.','Pour l’application de l’article L. 1221-22 aux contrats antérieurs, l’adaptation historique de son deuxième alinéa reste ainsi formulée : « de durées plus longues fixées par les accords collectifs de branche conclus avant le 1er janvier 2018, dans la limite d’une durée de cinq ans ». Elle ne remet en vigueur aucune dérogation ou stipulation dont l’effet a déjà cessé.'),'Ferme toute dérogation locale longue pour les nouveaux contrats tout en conservant la trace et le seul champ temporel de l’adaptation source.',common+'Contrôler l’effet temporel déjà expiré de la limite de cinq ans ; ne pas l’étendre de cinq ans à compter de la réforme.','Les essais plus courts du nouveau régime restent possibles à Mayotte. La dérogation historique n’est pas transformée en autorisation actuelle d’allonger l’essai et les droits d’un ancien contrat ne sont pas réduits par une restauration artificielle d’un accord expiré.')

put('L1226-4-3',P('Pour les contrats à durée déterminée conclus avant '+E+', la rupture pour inaptitude ouvre droit à une indemnité spéciale au moins égale au montant calculé selon le barème de l’article L. 1234-9, versée selon les modalités de l’indemnité de précarité de l’article L. 1243-8. Les droits antérieurs de calcul sont préservés.','Le salarié sous contrat de travail unique nouveau relève de la procédure d’inaptitude des articles L. 1226-2-1 et L. 1226-4. Il conserve, pour la rupture fondée sur cette inaptitude, une indemnité spéciale au moins égale au montant du barème de l’article L. 1234-9, calculé au prorata sans condition d’un an. La franchise de l’indemnité ordinaire ne supprime pas cette garantie spéciale. Les autres droits liés à l’inaptitude restent applicables.'),'Retire le CDD futur du régime d’inaptitude sans supprimer la garantie spéciale des faibles anciennetés.',common+'POINT DE PÉRIMÈTRE : garantie spéciale indépendante du seuil ordinaire ; ne pas écrire zéro par simple renvoi à l’ouverture de L1234-9. L1226-4 et son préavis non exécuté nécessitent la coordination complémentaire de root.','L’indemnité spécifique d’inaptitude reste disponible même avant un an pour les situations futures ; le contrat unique ne prive pas un salarié inapte de la garantie que la source attachait au contrat court. Les droits et modalités des contrats antérieurs demeurent réservés.')
put('L1226-20',P('Les dispositions particulières suivantes restent applicables aux contrats à durée déterminée conclus avant '+E+' :','Les deuxième et dernier alinéas de l’article L. 1226-12 et les articles L. 1226-14 à L. 1226-16 ne leur sont pas applicables. Les articles L. 1226-10 et L. 1226-11 le sont.','La rupture est possible si l’employeur justifie de l’impossibilité de proposer un emploi dans les conditions de ces deux articles, si le salarié refuse l’emploi proposé dans ces conditions, ou si l’avis médical mentionne expressément que tout maintien dans un emploi serait gravement préjudiciable à sa santé ou que son état interdit tout reclassement.','Cette rupture ouvre droit à une indemnité spéciale au moins égale au double du montant calculé selon l’article L. 1234-9, avec les droits antérieurs protégés. Elle est versée selon les modalités de l’indemnité de précarité de l’article L. 1243-8.','Pour le contrat de travail unique nouveau, les conditions, procédures et protections des articles L. 1226-10 à L. 1226-16 s’appliquent. Le minimum spécial double est calculé sur le barème de L. 1234-9 au prorata sans condition d’un an, indépendamment de la franchise ordinaire. Aucune fin automatique du contrat ne résulte de la fin d’une mission ou d’une formation.'),'Ferme le régime CDD nouveau tout en préservant reclassement, procédure et indemnisation spéciale de l’inaptitude professionnelle.',common+'Le double minimum est un droit spécifique à coordonner avec L1226-14, sans cumul de deux indemnités de même nature. Le préavis propre à l’inaptitude professionnelle doit être articulé par root.','La garantie spéciale double et les conditions protectrices de reclassement subsistent, y compris pour les faibles anciennetés futures. Aucun droit acquis des CDD antérieurs n’est effacé et la franchise ordinaire ne rend pas nul un minimum d’accident du travail ou de maladie professionnelle.')
put('L1233-68',P('Un accord conclu et agréé selon la section 5 du chapitre II du titre II du livre IV de la cinquième partie, à l’exception de l’article L. 5422-20-1 et du second alinéa de l’article L. 5422-22, fixe la mise en œuvre du contrat de sécurisation professionnelle, notamment :','1° Les conditions d’ancienneté ;','2° Les formalités d’adhésion et délais de réponse à la proposition de l’employeur ;','3° La durée du dispositif et son adaptation aux entreprises et bénéficiaires. Les périodes de travail auprès de tout employeur autre qu’un particulier prennent, pour les embauches à compter de '+E+', la forme d’un contrat de travail unique. La fin d’une période d’accompagnement ne fixe pas le terme de ce contrat ; les contrats antérieurs conservent leur régime transitoire ;','4° Le contenu, le financement, notamment au titre du compte personnel de formation, et la mise en œuvre des mesures de l’article L. 1233-65 par les organismes des articles L. 5311-2 à L. 5311-4 ;','5° La continuité des formations engagées pendant le dispositif ;','6° Les modalités de reprise éventuelle du dispositif après interruption pour reprise d’emploi, notamment après rupture du contrat de travail unique selon ses règles propres ;','7° Les obligations du bénéficiaire et les conditions d’une rupture du dispositif par les organismes du 4° en cas de manquement ;','8° Le montant de l’allocation et des éventuelles incitations financières au reclassement servies par l’institution de l’article L. 5312-1 pour le compte de l’organisme de l’article L. 5427-1, ainsi que suspension, interruption et cumul avec d’autres revenus de remplacement ;','9° Les règles d’assurance chômage, notamment l’imputation de la durée du dispositif sur l’allocation de l’article L. 5422-1 ;','10° La participation au financement des mesures du 4° :','a) De l’organisme de l’article L. 5427-1 ;','b) Des employeurs, par un versement représentatif de l’indemnité compensatrice de préavis, dans la limite de trois mois de salaire augmentés des cotisations et contributions obligatoires correspondantes. Le préavis nouveau de quinze jours ne devient pas un préavis fictif de trois mois.','À défaut d’accord ou d’agrément, un décret en Conseil d’État fixe la mise en œuvre et le financement du dispositif.','Les contrats de travail à durée déterminée de l’article L. 1242-3 et contrats de mission de l’article L. 1251-7 déjà conclus avant '+E+' restent régis par leurs dispositions transitoires ; aucune nouvelle conclusion ou prorogation à durée déterminée ne découle du présent article.'),'Supprime la porte CDD/intérim du CSP futur en maintenant le dispositif d’accompagnement, son allocation, sa formation et ses dix thèmes d’accord.',common+'Le contrat de sécurisation professionnelle est un dispositif, pas un contrat salarié soumis à l’interdiction des termes d’emploi. Le financement représentatif du préavis doit suivre L1233-67/69 ; il n’est ni inventé ni artificiellement porté à trois mois.','Les droits à allocation, reprise du dispositif, continuité de formation, incitations et financement existants restent ouverts. L’exclusion des particuliers est maintenue. La conversion du support d’emploi n’autorise pas à arrêter automatiquement le CDI pour faire reprendre le CSP ; le contrat doit être rompu selon ses règles.')
put('L1233-72-1',P('Le congé de reclassement peut être suspendu pendant des périodes de travail auprès de tout employeur autre qu’un particulier. Pour les embauches à compter de '+E+', le contrat de travail conclu pendant cette suspension est le contrat de travail unique de l’article L. 1221-2.','La durée prévue de cette période ne fixe pas le terme du contrat. Si le contrat prend fin selon ses règles propres pendant le congé restant, celui-ci reprend pour la durée restant à courir. L’employeur d’origine peut reporter le terme initial du congé à due concurrence de ces périodes de travail.','Les périodes de travail sous CDD de l’article L. 1242-3 ou contrat de mission de l’article L. 1251-7 déjà conclus avant cette entrée en vigueur restent soumises à la transition qui leur est applicable ; le présent article n’autorise aucun nouveau contrat d’emploi à terme.'),'Remplace les supports CDD/intérim nouveaux par le CDI unique et conserve la suspension et la reprise du congé.',common+'Le report éventuel du congé est une faveur distincte du terme du nouvel emploi ; aucun arrêt automatique du contrat à la fin de la période de reclassement.','La possibilité de travailler, la suspension, la reprise pour le reliquat et le report du congé demeurent. La durée déterminée de l’accompagnement ne transforme pas l’emploi nouveau en CDD et les contrats antérieurs gardent leurs droits de terme.')
put('L1237-18-1',P('Les périodes de travail du congé de mobilité peuvent se dérouler dans l’entreprise qui l’a proposé ou auprès d’un autre employeur.','Pour les embauches à compter de '+E+', elles sont accomplies sous contrat de travail unique, sans terme automatique lié à la période prévue par l’accord collectif. Les conditions d’activité et de suspension du congé sont fixées par cet accord. Si ce contrat est rompu selon ses règles propres avant l’épuisement des droits au congé, celui-ci reprend pour le reliquat prévu par l’accord.','Les CDD conclus avant cette entrée en vigueur en application du 1° de l’article L. 1242-3 demeurent soumis à leur transition : le congé est suspendu et reprend à leur terme pour sa durée restant à courir. Le présent article n’autorise aucune nouvelle conclusion ou reconduction de CDD.'),'Supprime le support CDD futur du congé de mobilité en conservant l’activité, la suspension et la reprise du reliquat.',common+'La note source sur l’ordonnance 2017-1387 et le 1er janvier 2018 reste une entrée en vigueur historique. La durée de l’accord ne constitue pas un terme nouveau du contrat de travail.','Les périodes d’activité internes et externes restent possibles et le reliquat de mobilité est conservé. Les bénéficiaires de contrats antérieurs ne perdent pas la reprise prévue à leur terme ; aucun employeur ne peut rompre automatiquement le CDI à la fin d’une période de congé.')

assert set(A)==set(by),(set(by)-set(A),set(A)-set(by))
removed={
 'L1221-2':'Suppression de la faculté de conclure ou renouveler un contrat salarié à terme pour les embauches nouvelles ; les droits des contrats antérieurs restent transitoires.',
 'L1221-21':'Suppression de toute possibilité de renouveler la période d’essai du contrat nouveau, même lorsque sa durée initiale est inférieure à trois mois.',
 'L1221-25':'Remplacement du barème de prévenance employeur de 24 heures, 48 heures, deux semaines et un mois par quinze jours calendaires pour le contrat nouveau, sans perte du reliquat payé.',
 'L1221-26':'Remplacement des prévenances salariées de 24 ou 48 heures par quinze jours calendaires pour le contrat nouveau, sans double préavis en franchissant le terme d’essai.',
 'L1234-1':'Suppression pour le contrat nouveau des préavis dépendant de six mois ou deux ans d’ancienneté et des durées d’un et deux mois ; préavis unique de quinze jours payé en cas de dispense.',
 'L1234-2':'Suppression pour le contrat nouveau de la possibilité de faire varier le préavis unilatéral par clause ; la durée uniforme est distincte d’une dispense d’exécution.',
 'L1234-8':'Suppression des conditions d’ancienneté déterminant la durée du préavis nouveau ; aucun seuil d’ancienneté pour les quinze jours.',
 'L1234-15':'Suppression pour le contrat nouveau des quatre préavis locaux dépendant de la périodicité de rémunération ; maintien de quinze jours calendaires et de l’ancien régime pour anciens contrats.',
 'L1234-16':'Suppression pour les nouveaux contrats des six semaines locales réservées aux catégories professionnelles énumérées ; préavis nouveau de quinze jours, autres protections distinctes.',
 'L1234-17-1':'Suppression pour les nouveaux contrats de la priorité locale des durées de préavis plus longues ; conservation de la recherche d’emploi et des droits des anciens contrats.',
 'L1237-1':'Suppression pour les nouveaux contrats du préavis de démission variable selon conventions et usages ; durée unique de quinze jours, dispenses légales spéciales distinctes.',
 'L1233-68':'Suppression de la nouvelle embauche CDD ou du contrat de mission salarié à terme comme support d’une période de travail du CSP ; maintien de l’accompagnement, des allocations et des formations.',
 'L1233-72-1':'Suppression des nouveaux CDD et contrats de mission salariés à terme pendant le congé de reclassement ; maintien des périodes d’activité sous contrat unique et de la reprise du reliquat.',
 'L1237-18-1':'Suppression des nouveaux CDD pendant les périodes de travail du congé de mobilité ; maintien du travail, de la suspension et de la reprise des droits au congé.',
}
